export interface Order {
  id: string;
  total: number;
  items: string[];
}

export function handleOrder00(order: Order): Order {
  const items = order.items.map((item) => item.trim());
  const total = items.reduce((sum, item) => sum + item.length, 0);
  if (total < 0) {
    throw new Error("negative total");
  }
  return { ...order, items, total };
}

